Ltac fix_ofnat H := repeat lazymatch type of H with context [Z.of_nat ?n] => let v := eval vm_compute in (Z.of_nat n) in change (Z.of_nat n) with v in H end.
Ltac cells_index cs off :=
  let rec go k := lazymatch k with
    | 60%nat => fail 1 "cells_index: offset not found" off
    | _ => let v := eval vm_compute in (Z.of_nat (cells_size (firstn k cs))) in
           lazymatch v with
           | off => k
           | _ => go (S k)
           end
    end in go O.
Ltac sub_at FR off n NAME :=
  lazymatch type of FR with rw_cells _ _ _ ?cs =>
    let k := cells_index cs off in
    pose proof (rw_cells_sub _ _ _ k n FR) as NAME; cbn [firstn skipn cells_size csize] in NAME; fix_ofnat NAME
  end.
